import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import { componentsEn, componentsVi } from "./i18n/componentsPhaseEBatch3.js";
import { publicFeedExploreEn, publicFeedExploreVi } from "./i18n/publicFeedExploreResources.js";
import { exploreCapabilitiesEn, exploreCapabilitiesVi } from "./i18n/exploreCapabilitiesResources.js";
import { activationDiscoveryEn, activationDiscoveryVi } from "./i18n/activationDiscoveryResources.js";

// Standardized storage key - shared across all Cardbey apps
const STORAGE_KEY = 'cardbey.lang';

/** Deep-merge Phase E Batch 3 component keys into translation.components */
function deepMerge(target, source) {
  if (!target || !source) return;
  for (const key of Object.keys(source)) {
    const srcVal = source[key];
    const tgtVal = target[key];
    if (
      srcVal &&
      typeof srcVal === "object" &&
      !Array.isArray(srcVal) &&
      tgtVal &&
      typeof tgtVal === "object" &&
      !Array.isArray(tgtVal)
    ) {
      deepMerge(tgtVal, srcVal);
    } else {
      target[key] = srcVal;
    }
  }
}

function deepMergeComponents(target, source) {
  deepMerge(target, source);
}

