/**
 * Auto-detect language from browser with SSR guards
 * Priority: URL param (?lang=en|vi) > localStorage > browser language > default to 'en'
 */
function detectInitialLanguage() {
  // SSR guard
  if (typeof window === 'undefined') {
    return 'en';
  }

  // Check URL param first (for cross-app navigation)
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const urlLang = urlParams.get('lang');
    if (urlLang === 'en' || urlLang === 'vi') {
      // Normalize to lowercase and persist
      const normalized = urlLang.toLowerCase();
      localStorage.setItem(STORAGE_KEY, normalized);
      return normalized;
    }
  } catch (error) {
    // Ignore URL param parsing errors
  }

  // Try reading from localStorage
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved === 'en' || saved === 'vi') {
    // Normalize to lowercase
    return saved.toLowerCase();
  }

  // Auto-detect from browser
  try {
    const browserLang =
      (typeof navigator !== 'undefined' && navigator.languages && navigator.languages[0]) ||
      (typeof navigator !== 'undefined' && navigator.language) ||
      'en';
    
    const normalized = browserLang.toLowerCase();
    const initialLang = normalized.startsWith('vi') ? 'vi' : 'en';
    // Persist detected language
    localStorage.setItem(STORAGE_KEY, initialLang);
    return initialLang;
  } catch (error) {
    // Fallback to 'en' if detection fails
    console.warn('[i18n] Language detection failed, defaulting to en:', error);
    return 'en';
  }
}

deepMergeComponents(resources.en.translation.components, componentsEn);
deepMergeComponents(resources.vi.translation.components, componentsVi);
deepMerge(resources.en.translation, publicFeedExploreEn);
deepMerge(resources.vi.translation, publicFeedExploreVi);
deepMerge(resources.en.translation.explore, { capabilities: exploreCapabilitiesEn });
deepMerge(resources.vi.translation.explore, { capabilities: exploreCapabilitiesVi });
deepMerge(resources.en.translation, activationDiscoveryEn);
deepMerge(resources.vi.translation, activationDiscoveryVi);

const initialLng = detectInitialLanguage();

i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: initialLng,
    fallbackLng: "en",
    supportedLngs: ["en", "vi"],
    ns: ["translation", "dashboard", "features", "booking"],
    defaultNS: "translation",
    interpolation: { escapeValue: false },
  });

// Set document lang attribute (SSR guard)
if (typeof document !== 'undefined') {
document.documentElement.setAttribute("lang", initialLng);
}

/**
 * Set language and persist to localStorage
 * @param {string} lng - Language code ('en' | 'vi')
 */
export function setLanguage(lng) {
  // Normalize to lowercase
  const normalized = typeof lng === 'string' ? lng.toLowerCase() : 'en';
  
  if (normalized !== 'en' && normalized !== 'vi') {
    console.warn(`[i18n] Invalid language: ${lng}, defaulting to 'en'`);
    lng = 'en';
  } else {
    lng = normalized;
  }

  i18n.changeLanguage(lng);
  
  // Persist to localStorage (SSR guard)
  if (typeof window !== 'undefined') {
    localStorage.setItem(STORAGE_KEY, lng);
    try {
      localStorage.setItem('cardbey.preferredLocale', lng);
    } catch {
      /* ignore */
    }
    
    // Remove lang param from URL if present (to avoid confusion)
    try {
      const url = new URL(window.location.href);
      if (url.searchParams.has('lang')) {
        url.searchParams.delete('lang');
        window.history.replaceState({}, '', url.toString());
      }
    } catch (error) {
      // Ignore URL manipulation errors
    }
  }
  
  // Update document lang attribute (SSR guard)
  if (typeof document !== 'undefined') {
  document.documentElement.setAttribute("lang", lng);
  }
}

// Export storage key for other apps to read
export { STORAGE_KEY };

// Cross-tab live sync: Listen for storage events from other tabs
if (typeof window !== 'undefined') {
  window.addEventListener('storage', (event) => {
    if (event.key === STORAGE_KEY && event.newValue) {
      const nextLang = event.newValue.toLowerCase();
      // Only update if it's a valid language and different from current
      if ((nextLang === 'en' || nextLang === 'vi') && i18n.language !== nextLang) {
        i18n.changeLanguage(nextLang);
        // Update document lang attribute
        if (typeof document !== 'undefined') {
          document.documentElement.setAttribute('lang', nextLang);
        }
      }
    }
  });
}

export default i18n;

